    questions: [ {q:"Did a hungry bear appear on the path?", a_en:"Yes", a_tr:"Evet"}, {q:"Did both friends climb the tree?", a_en:"No", a_tr:"Hayır"}, {q:"Did the second friend pretend to be dead?", a_en:"Yes", a_tr:"Evet"}, {q:"Do bears usually eat dead animals?", a_en:"No", a_tr:"Hayır"}, {q:"Did the bear smell the man's ears?", a_en:"Yes", a_tr:"Evet"}, {q:"Did the bear kill the man on the ground?", a_en:"No", a_tr:"Hayır"}, {q:"Should you travel with friends who leave you in danger?", a_en:"No", a_tr:"Hayır"} ]
