    questions: [ {q:"Did the butterfly struggle to come out of its cocoon?", a_en:"Yes", a_tr:"Evet"}, {q:"Did the young monk cut the cocoon?", a_en:"Yes", a_tr:"Evet"}, {q:"Did the butterfly fly away immediately?", a_en:"No", a_tr:"Hayır"}, {q:"Were the butterfly's wings strong?", a_en:"No", a_tr:"Hayır"}, {q:"Does the struggle help the butterfly's muscles?", a_en:"Yes", a_tr:"Evet"}, {q:"Did the young monk's help hurt the butterfly?", a_en:"Yes", a_tr:"Evet"}, {q:"Can the butterfly fly now?", a_en:"No", a_tr:"Hayır"} ]
