    questions: [ {q:"Did the fox know a hundred tricks?", a_en:"Yes", a_tr:"Evet"}, {q:"Did the cat know many tricks?", a_en:"No", a_tr:"Hayır"}, {q:"Did the cat climb a tall tree?", a_en:"Yes", a_tr:"Evet"}, {q:"Could the dogs reach the cat?", a_en:"No", a_tr:"Hayır"}, {q:"Was the fox confused by his many plans?", a_en:"Yes", a_tr:"Evet"}, {q:"Did the dogs catch the fox?", a_en:"Yes", a_tr:"Evet"}, {q:"Is a simple plan often better?", a_en:"Yes", a_tr:"Evet"} ]
