    questions: [ {q:"Was the crow jealous of the peacocks?", a_en:"Yes", a_tr:"Evet"}, {q:"Did the crow find colorful feathers on the ground?", a_en:"Yes", a_tr:"Evet"}, {q:"Did the crow stick the feathers into his tail?", a_en:"Yes", a_tr:"Evet"}, {q:"Were the peacocks happy to see him?", a_en:"No", a_tr:"Hayır"}, {q:"Did the peacocks peck the crow?", a_en:"Yes", a_tr:"Evet"}, {q:"Did his old crow friends accept him back?", a_en:"No", a_tr:"Hayır"}, {q:"Is the crow now entirely alone?", a_en:"Yes", a_tr:"Evet"} ]
