    questions: [ {q:"Were the mice afraid of the cat?", a_en:"Yes", a_tr:"Evet"}, {q:"Did the young mouse have an idea?", a_en:"Yes", a_tr:"Evet"}, {q:"Was the plan to tie a bell on the cat?", a_en:"Yes", a_tr:"Evet"}, {q:"Did all the mice cheer for the plan?", a_en:"Yes", a_tr:"Evet"}, {q:"Did an old mouse ask a difficult question?", a_en:"Yes", a_tr:"Evet"}, {q:"Did any mouse volunteer to put the bell on?", a_en:"No", a_tr:"Hayır"}, {q:"Is a clever plan easy to execute?", a_en:"No", a_tr:"Hayır"} ]
