    questions: [ {q:"Were the peasant and the snake friends at first?", a_en:"Yes", a_tr:"Evet"}, {q:"Did the snake give the man gold coins?", a_en:"Yes", a_tr:"Evet"}, {q:"Was the peasant's son greedy?", a_en:"Yes", a_tr:"Evet"}, {q:"Did the son kill the snake?", a_en:"No", a_tr:"Hayır"}, {q:"Did the snake bite the son?", a_en:"Yes", a_tr:"Evet"}, {q:"Did the son survive?", a_en:"No", a_tr:"Hayır"}, {q:"Could they be friends again at some point?", a_en:"No", a_tr:"Hayır"} ]
